def _sr_in_web_path(st, a):
    seg = st[max(0, a - 512):a]
    i = seg.rfind("://")
    if i < 0 or not seg[max(0, i - 5):i].lower().endswith(("http", "https")):
        return False
    return _SR_WEB_PATH_END.search(seg, i + 3) is None


