_SR_DATA_URI = _sr_re.compile(
    r"data:[A-Za-z0-9.+/-]{1,64}(?:;[A-Za-z0-9=._-]{1,64}){0,4};base64,[A-Za-z0-9+/=]*")
_SR_B64_RUN = _sr_re.compile(r"(?<![A-Za-z0-9+/=])[A-Za-z0-9+/=]{200,}")
_SR_PATH_PREFIX = _sr_re.compile(r"(?:/[A-Za-z0-9+=]{1,64}){1,32}/")
_SR_B64_UPPER, _SR_B64_LOWER, _SR_B64_DIGIT = (_sr_re.compile(c) for c in ("[A-Z]", "[a-z]", "[0-9]"))
_SR_WRAP_SEP = r"(?:\r?\n|(?:\\{1,2}r)?\\{1,2}n)"
_SR_B64_WRAPPED = _sr_re.compile(
    r"(?:(?<![A-Za-z0-9+/=])|(?<=\\n)|(?<=\\r))(?:"
    + "|".join(r"(?:[A-Za-z0-9+/]{%d}%s){2,}(?:[A-Za-z0-9+/]{%d}(?:%s[A-Za-z0-9+/]{0,%d}={1,2})?"
               r"|[A-Za-z0-9+/]{%d}=|[A-Za-z0-9+/]{%d}==)(?![A-Za-z0-9+/=])"
               % (w, _SR_WRAP_SEP, w, _SR_WRAP_SEP, w - 1, w - 1, w - 2) for w in (76, 64)) + ")")


_SR_PEMC_BEGIN = _sr_re.compile(r"-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----", _sr_re.I)
_SR_PEMC_END = _sr_re.compile(r"-----END [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----", _sr_re.I)
_SR_PEMC_LONG = _sr_re.compile(r"[A-Za-z0-9+/]{40,76}={0,2}")
_SR_PEMC_SHORT = _sr_re.compile(r"[A-Za-z0-9+/]{1,76}={0,2}|=[A-Za-z0-9+/]{4}")
_SR_PEMC_HDR = _sr_re.compile(r"[A-Za-z][A-Za-z0-9-]{1,31}: [^\n]{0,200}")
_SR_PEMC_PEMHDR = _sr_re.compile(r"(?:Proc-Type|DEK-Info): [^\n]{0,200}", _sr_re.I)
_SR_PEMC_BODY = (("PGP", _sr_re.compile(r"l[A-Q]|x[Q-d]")),
                 ("OPENSSH", _sr_re.compile(r"b3BlbnNzaC1rZXktdjE")))
_SR_PEMC_BODY_DER = _sr_re.compile(r"M[A-I]")
SR_PEMC_MAX_LINES = 200
SR_PEMC_MAX_BYTES = 65536
SR_PEMC_MARK = "[REDACTED-PRIVATE-KEY]"


class SrPemCarry:
    __slots__ = ("open", "started", "hdr", "empty", "kind", "lines", "nbytes", "seen", "hits")

    def __init__(self):
        self.open = self.started = self.hdr = self.empty = self.seen = False
        self.kind = ""
        self.lines = self.nbytes = self.hits = 0

    def begin(self, kind="", started=False, hdr=True, empty=False):
        self.open, self.started, self.hdr, self.empty, self.kind = True, started, hdr, empty, kind
        self.lines = self.nbytes = 0
        self.seen = True

    def close(self):
        self.open = self.started = self.hdr = self.empty = False

    def end_record(self):
        if self.open and not self.seen:
            self.close()
        self.seen = self.started = False


def _sr_pemc_line(core, started):
    return bool(_SR_PEMC_LONG.fullmatch(core) or _SR_PEMC_HDR.fullmatch(core)
                or (started and (core == "" or _SR_PEMC_SHORT.fullmatch(core))))


def _sr_pemc_step(core, started, hdr):
    if _SR_PEMC_LONG.fullmatch(core):
        return True, True, False
    if _SR_PEMC_HDR.fullmatch(core):
        return True, started, True
    if core == "":
        return (True, started, False) if started or hdr else (False, started, hdr)
    if started and _SR_PEMC_SHORT.fullmatch(core):
        return True, True, False
    return False, started, hdr


def sr_pem_opens(text):
    if "-----" not in text:
        return None
    last = None
    for last in _SR_PEMC_BEGIN.finditer(text):
        pass
    if last is None or _SR_PEMC_END.search(text, last.end()):
        return None
    rest = text[last.end():].split("\n")
    if len(rest) > SR_PEMC_MAX_LINES or rest[0].rstrip("\r").strip(" \t"):
        return None
    if len(rest) > 1 and not rest[-1]:
        rest.pop()
    started, hdr, got = False, True, False
    for ln in rest[1:]:
        core = ln.rstrip("\r").strip(" \t")
        ok, started, hdr = _sr_pemc_step(core, started, hdr)
        if not ok:
            return None
        got = got or bool(core)
    return last.start(), last.group(0)[11:-5].upper(), started, hdr, got


def _sr_pemc_body_start(core, kind):
    for word, pat in _SR_PEMC_BODY:
        if word in kind:
            return pat.match(core) is not None
    return _SR_PEMC_BODY_DER.match(core) is not None


def _sr_pemc_lines(text):
    i = 0
    while True:
        j = text.find("\n", i)
        if j < 0:
            yield text[i:]
            return
        yield text[i:j]
        i = j + 1


def _sr_pemc_completes(texts, carry):
    started, hdr, n, nb = carry.started, carry.hdr, 0, 0
    for t in texts:
        if not isinstance(t, str):
            break
        for ln in _sr_pemc_lines(t):
            core = ln.rstrip("\r").strip(" \t")
            m = _SR_PEMC_END.match(core)
            if m:
                return n > 0 and m.group(0)[9:-5].upper() == carry.kind
            if n == 0 and _SR_PEMC_PEMHDR.fullmatch(core):
                return True
            was = started
            ok, started, hdr = _sr_pemc_step(core, started, hdr)
            if not ok:
                return False if n else None
            if started and not was and _sr_pemc_body_start(core, carry.kind):
                return True
            n += bool(core)
            nb += len(ln) + 1
            if n >= SR_PEMC_MAX_LINES or nb >= SR_PEMC_MAX_BYTES:
                return False
    return False if n else None


def _sr_pemc_mark(text, end):
    return SR_PEMC_MARK + "".join(c for c in text[:end] if c in "\r\n") + text[end:]


def sr_pem_continue(text, carry):
    if carry.empty:
        ok = _sr_pemc_completes((text,), carry)
        if not ok:
            if ok is False:
                carry.close()
            return text
        carry.empty = False
    started, hdr = carry.started, carry.hdr
    pos = n = nb = body = 0
    for ln in text.split("\n"):
        core = ln.rstrip("\r").strip(" \t")
        m = _SR_PEMC_END.match(core)
        if m:
            mention = not started and carry.lines + n == 0
            carry.close()
            if mention:
                return text
            carry.seen = True
            return _sr_pemc_mark(text, pos + ln.index(m.group(0)) + len(m.group(0)))
        ok, started, hdr = _sr_pemc_step(core, started, hdr)
        if not ok:
            if body:
                carry.close()
                return _sr_pemc_mark(text, pos - 1)
            if carry.started:
                carry.close()
            return text
        n += 1
        nb += len(ln) + 1
        pos += len(ln) + 1
        body += bool(core)
        if carry.lines + n >= SR_PEMC_MAX_LINES or carry.nbytes + nb >= SR_PEMC_MAX_BYTES:
            carry.close()
            return _sr_pemc_mark(text, min(pos, len(text))) if body else text
    if not body:
        return text
    carry.started, carry.hdr, carry.seen = started, hdr, True
    carry.lines += n
    carry.nbytes += nb
    return _sr_pemc_mark(text, len(text))


def sr_pem_orphan_end(text):
    return sr_pem_orphan_redact(text)[0]


def sr_pem_walk(node, carry):
    if isinstance(node, str):
        out = node
        if carry.open:
            out = sr_pem_continue(node, carry)
        if out == node and "-----" in node:
            out = sr_pem_orphan_end(node)
            if out != node:
                carry.close()
        o = sr_pem_opens(node)
        if o is not None:
            at, kind, started, hdr, got = o
            carry.begin(kind, started, hdr, empty=not got)
            cut = len(out) - (len(node) - at)
            if got and cut >= 0 and out[cut:] == node[at:]:
                out = out[:cut] + _sr_pemc_mark(out[cut:], len(out) - cut)
        if out != node:
            carry.hits += 1
        return out
    if isinstance(node, list):
        out = []
        for i, v in enumerate(node):
            if carry.open and carry.empty and isinstance(v, str):
                ok = _sr_pemc_completes((node[j] for j in range(i, len(node))), carry)
                if ok:
                    carry.empty = False
                elif ok is False:
                    carry.close()
            out.append(sr_pem_walk(v, carry))
        return out
    if isinstance(node, dict):
        return {k: sr_pem_walk(v, carry) for k, v in node.items()}
    return node


def _sr_pemc_list_body(text, elems, kind):
    for a, z in elems[1:]:
        core = text[a:z].strip(" \t")
        if _SR_PEMC_PEMHDR.fullmatch(core):
            return True
        if _SR_PEMC_LONG.fullmatch(core):
            return _sr_pemc_body_start(core, kind)
    return False


def sr_pem_list_redact(text):
    if "-----" not in text:
        return text, 0
    out, pos, found = [], 0, 0
    for b in _SR_PEMC_BEGIN.finditer(text):
        if b.start() < pos:
            continue
        i = b.start()
        q0 = i - 1
        while q0 > 0 and text[q0 - 1] == "\\":
            q0 -= 1
        if i == 0 or text[i - 1] not in "\"'":
            continue
        qtok = text[q0:i]
        if not text.startswith(qtok, b.end()):
            continue
        elems = [(b.start(), b.end())]
        k, closed, total = b.end() + len(qtok), False, 0
        while len(elems) <= SR_PEMC_MAX_LINES and total < SR_PEMC_MAX_BYTES:
            sep = k
            while sep < len(text) and text[sep] in " \t\r\n,":
                sep += 1
            if sep == k or "," not in text[k:sep] or not text.startswith(qtok, sep):
                break
            s0 = sep + len(qtok)
            s1 = text.find(qtok, s0, s0 + 300)
            if s1 < 0:
                break
            core = text[s0:s1].strip(" \t")
            if _SR_PEMC_END.fullmatch(core):
                elems.append((s0, s1))
                closed = True
                break
            if not (_sr_pemc_line(core, len(elems) > 1) or (core == "" and len(elems) == 1)):
                break
            elems.append((s0, s1))
            total += s1 - s0
            k = s1 + len(qtok)
        if len(elems) < 2 or not (closed or _sr_pemc_list_body(text, elems, b.group(0)[11:-5].upper())):
            continue
        for a, z in elems:
            out.append(text[pos:a])
            out.append(SR_PEMC_MARK)
            pos = z
        found += 1
    if not found:
        return text, 0
    out.append(text[pos:])
    return "".join(out), found


_SR_PEMQ_BODY = _sr_re.compile(r"[A-Za-z0-9+/= \t:,.\\-]{0,%d}" % SR_PEMC_MAX_BYTES)
_SR_PEMQ_NL = _sr_re.compile(r"\\+(?:r\\+)?n|\\+r")
_SR_PEMQ_DNL = r"\$'(?:\\{1,8}r)?\\{1,8}n'"
_SR_PEMQ_SEP = _sr_re.compile(r"(?:[ \t\r\n+.]|\\\r?\n|\\{1,8}[nrt]|" + _SR_PEMQ_DNL + "){0,256}")
_SR_PEMQ_DNL_RE = _sr_re.compile(_SR_PEMQ_DNL)
_SR_PEMQ_PREFIX = _sr_re.compile(r"(?:[bBrRuUfF]{1,2}|@)?")
_SR_PEMQ_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/= \t:,.\\-")
SR_PEMQ_MAX_PIECES = 2 * SR_PEMC_MAX_LINES


def _sr_pemq_piece(text, p, qtok):
    a = p + len(qtok)
    z = _SR_PEMQ_BODY.match(text, a).end()
    bs = qtok[:-1]
    if z >= len(text) or text[z] != qtok[-1] or (bs and text[z - len(bs):z] != bs) or z - len(bs) < a:
        return None
    return a, z - len(bs), z + 1


def _sr_pemq_lines(content):
    parts = _SR_PEMQ_NL.split(content)
    if len(parts) > 1 and parts[-1] == "":
        parts.pop()
    return [x.strip(" \t") for x in parts]


def _sr_pemq_scan(lines, st):
    for i, core in enumerate(lines):
        if st["end"]:
            return False
        if _SR_PEMC_END.fullmatch(core):
            st["end"] = True
            continue
        if _SR_PEMC_BEGIN.fullmatch(core):
            return False
        if _SR_PEMC_LONG.fullmatch(core):
            if st["first"] is None:
                st["first"] = core
            st["started"] = st["long"] = True
        elif core == "":
            continue
        elif _SR_PEMC_PEMHDR.fullmatch(core) or (not st["started"] and _SR_PEMC_HDR.fullmatch(core)):
            if st["started"]:
                return False
            st["hdr"] = True
        elif st["started"] and _SR_PEMC_SHORT.fullmatch(core):
            continue
        else:
            return False
    return True


def _sr_pemq_qtok(text, i):
    if i == 0 or text[i - 1] not in "'\"":
        return None
    j = i - 1
    while j > 0 and text[j - 1] == "\\" and i - 1 - j < 16:
        j -= 1
    return text[j:i]


def sr_pem_concat_spans(text):
    if "-----" not in text:
        return [], 0
    spans, pos, keys = [], 0, 0
    for b in _SR_PEMC_BEGIN.finditer(text):
        if b.start() < pos:
            continue
        qtok = _sr_pemq_qtok(text, b.start())
        if qtok is None:
            continue
        p = b.start() - len(qtok)
        pieces, st, total = [], {"started": False, "long": False, "first": None, "end": False, "hdr": False}, 0
        k = p
        while len(pieces) < SR_PEMQ_MAX_PIECES and total < SR_PEMC_MAX_BYTES:
            pc = _sr_pemq_piece(text, k, qtok)
            if pc is None:
                break
            lines = _sr_pemq_lines(text[pc[0]:pc[1]])
            if pieces:
                if lines and _SR_PEMC_BEGIN.fullmatch(lines[0]):
                    break
                save = dict(st)
                if not _sr_pemq_scan(lines, st):
                    st = save
                    break
            else:
                if not lines or not _SR_PEMC_BEGIN.fullmatch(lines[0]) or not _sr_pemq_scan(lines[1:], st):
                    break
            pieces.append((pc[0], pc[1]))
            total += pc[2] - k
            k = pc[2]
            if st["end"]:
                break
            k2 = _SR_PEMQ_SEP.match(text, k).end()
            k2 = _SR_PEMQ_PREFIX.match(text, k2).end()
            if not text.startswith(qtok, k2):
                break
            k = k2
        if pieces:
            pos = max(pos, pieces[-1][1])
        kind = b.group(0)[11:-5].upper()
        ok = len(pieces) >= 2 and st["long"] and (st["end"] or (st["first"] is not None
                                                               and _sr_pemc_body_start(st["first"], kind)))
        if ok:
            spans.extend(pieces)
            keys += 1
            pos = pieces[-1][1]
    lo = 0
    taken = [e for _s, e in spans]
    for e in _SR_PEMC_END.finditer(text):
        i = _sr_bisect.bisect_left(taken, e.end())
        if i < len(spans) and spans[i][0] <= e.start():
            lo = max(lo, e.end())
            continue
        floor = max(lo, spans[i - 1][1] if i else 0)
        lo = e.end()
        piece = _sr_pemq_tail(text, e, floor)
        if piece:
            spans.extend(piece)
            keys += 1
    spans.sort()
    return spans, keys


def _sr_pemq_tail(text, e, floor):
    a = e.start()
    while a > floor and a > e.start() - SR_PEMC_MAX_BYTES and text[a - 1] in _SR_PEMQ_CHARS:
        a -= 1
    qtok = _sr_pemq_qtok(text, a)
    if qtok is None or a - len(qtok) < floor:
        return []
    pc = _sr_pemq_piece(text, a - len(qtok), qtok)
    if pc is None or pc[1] < e.end():
        return []
    lines = _sr_pemq_lines(text[pc[0]:pc[1]])
    st = {"started": True, "long": False, "first": None, "end": False, "hdr": False}
    if not _sr_pemq_scan(lines, st) or not st["end"]:
        return []
    pieces = [(pc[0], pc[1])]
    k, total = pc[0] - len(qtok), pc[2] - pc[0]
    while len(pieces) < SR_PEMQ_MAX_PIECES and total < SR_PEMC_MAX_BYTES:
        j, n = k, 0
        while j > floor and n < 256:
            if text[j - 1] in "bBrRuUfF@" and n == 0 and j - 1 > floor and text[j - 2] in " \t\r\n+.'\"":
                j -= 1
            elif text[j - 1] in " \t\r\n+.":
                j -= 1
            elif text[j - 1] == "'" and text.rfind("$'", max(floor, j - 24), j - 1) >= 0 \
                    and _SR_PEMQ_DNL_RE.fullmatch(text, text.rfind("$'", max(floor, j - 24), j - 1), j):
                j = text.rfind("$'", max(floor, j - 24), j - 1)
            elif j - 2 >= floor and text[j - 2] == "\\" and text[j - 1] in "nrt\n":
                j -= 2
                while j > floor and text[j - 1] == "\\" and k - j < 256:
                    j -= 1
            else:
                break
            n += 1
        if j <= floor or not text.endswith(qtok, floor, j):
            break
        z = j - len(qtok)
        c = z
        while c > floor and z - c < SR_PEMC_MAX_BYTES and text[c - 1] in _SR_PEMQ_CHARS:
            c -= 1
        if _sr_pemq_qtok(text, c) != qtok or c - len(qtok) < floor:
            break
        lines = _sr_pemq_lines(text[c:z])
        if lines and (_SR_PEMC_BEGIN.fullmatch(lines[0]) or _SR_PEMC_END.fullmatch(lines[-1])):
            break
        probe = {"started": True, "long": False, "first": None, "end": False, "hdr": False}
        if not lines or not _sr_pemq_scan(lines, probe) or probe["hdr"]:
            break
        st["long"] = st["long"] or probe["long"] or (len(pieces) == 1 and bool(
            [x for x in lines if x] and _SR_PEMC_PADDED.fullmatch([x for x in lines if x][-1])))
        pieces.append((c, z))
        total += j - c
        k = c - len(qtok)
    if not st["long"] or len(pieces) < 2:
        return []
    return pieces


def sr_pem_concat_redact(text):
    spans, keys = sr_pem_concat_spans(text)
    if not spans:
        return text, 0
    out, pos = [], 0
    for a, z in spans:
        out.append(text[pos:a])
        out.append(SR_PEMC_MARK)
        pos = z
    out.append(text[pos:])
    return "".join(out), keys


_SR_PEMC_LNUM = _sr_re.compile(r"[ \t]*[0-9]{1,9}(?:→|\t)")
_SR_PEMC_QUOTE = _sr_re.compile(r"[ \t]*(?:[>#*│|][ \t]*){1,4}")
_SR_PEMC_PADDED = _sr_re.compile(r"[A-Za-z0-9+/]{14,76}={1,2}")


def _sr_pemc_core(line):
    core = line.rstrip("\r")
    q = _SR_PEMC_QUOTE.match(core)
    if q:
        core = core[q.end():]
    m = _SR_PEMC_LNUM.match(core)
    if m:
        core = core[m.end():]
    return core.strip(" \t")


def sr_pem_orphan_spans(text):
    if "-----" not in text:
        return []
    begins = [m.start() for m in _SR_PEMC_BEGIN.finditer(text)]
    spans, lo = [], 0
    for m in _SR_PEMC_END.finditer(text):
        i = _sr_bisect.bisect_left(begins, lo)
        floor, lo = lo, m.end()
        if i < len(begins) and begins[i] < m.start():
            continue
        nl = text.rfind("\n", floor, m.start())
        if nl < 0 or _sr_pemc_core(text[nl + 1:m.start()]):
            sp = _sr_pemc_orphan_escaped(text, m, floor)
            if sp:
                spans.append(sp)
            continue
        start, full, pos, n = nl + 1, False, nl, 0
        while pos > floor and n < SR_PEMC_MAX_LINES:
            prev = text.rfind("\n", floor, pos)
            if prev < 0 and floor:
                break
            core = _sr_pemc_core(text[prev + 1:pos])
            if not _sr_pemc_line(core, True) or (_SR_PEMC_HDR.fullmatch(core)
                                                 and not _SR_PEMC_PEMHDR.fullmatch(core)):
                break
            full = full or bool(_SR_PEMC_LONG.fullmatch(core)) or (n == 0 and bool(_SR_PEMC_PADDED.fullmatch(core)))
            start, pos, n = prev + 1, prev, n + 1
            if prev < 0:
                break
        if full:
            spans.append((start, m.end()))
    return spans


def _sr_pemc_orphan_escaped(text, m, floor):
    e = m.start()
    if e < 2 or text[e - 1] != "n" or text[e - 2] != "\\":
        return None
    k = 1
    while e - 1 - k > floor and text[e - 2 - k] == "\\" and k < 16:
        k += 1
    tok = "\\" * k + "n"
    cr = "\\" * k + "r"
    start, full, pos, n = None, False, e - len(tok), 0
    while pos > floor and n < SR_PEMC_MAX_LINES:
        prev = text.rfind(tok, floor, pos)
        a = prev + len(tok) if prev >= 0 else floor
        seg = text[a:pos]
        seg = seg[:-len(cr)] if seg.endswith(cr) else seg
        core = _sr_pemc_core(seg)
        if not _sr_pemc_line(core, True) or _SR_PEMC_HDR.fullmatch(core) or "\n" in seg:
            q = max(seg.rfind('"'), seg.rfind("'"))
            tail = seg[q + 1:]
            if q >= 0 and (_SR_PEMC_LONG.fullmatch(tail.strip(" \t"))
                           or (n == 0 and _SR_PEMC_PADDED.fullmatch(tail.strip(" \t")))):
                start, full = a + q + 1, True
            break
        full = full or bool(_SR_PEMC_LONG.fullmatch(core)) or (n == 0 and bool(_SR_PEMC_PADDED.fullmatch(core)))
        start, pos, n = a, prev, n + 1
        if prev < 0:
            break
    return (start, m.end()) if full and start is not None else None


_SR_PEMC_ESC_BREAK = _sr_re.compile(r"\\+[rn]")


def sr_pem_breaks(seg):
    raw = "".join(c for c in seg if c in "\r\n")
    return raw or "".join(_SR_PEMC_ESC_BREAK.findall(seg))


def sr_pem_orphan_redact(text):
    spans = sr_pem_orphan_spans(text)
    if not spans:
        return text, 0
    out, pos = [], 0
    for a, z in spans:
        out.append(text[pos:a])
        out.append(SR_PEMC_MARK + sr_pem_breaks(text[a:z]))
        pos = z
    out.append(text[pos:])
    return "".join(out), len(spans)


def sr_binary_spans(text):
    spans = [m.span() for m in _SR_DATA_URI.finditer(text)]
    for m in _SR_B64_RUN.finditer(text):
        r, start = m.group(0), m.start()
        if r[0] == "/":
            pm = _SR_PATH_PREFIX.match(r)
            if pm:
                r, start = r[pm.end() - 1:], start + pm.end() - 1
                if len(r) < 200:
                    continue
        if ("+" in r and r.count("/") * 16 < len(r) and _SR_B64_UPPER.search(r)
                and _SR_B64_LOWER.search(r) and _SR_B64_DIGIT.search(r)):
            spans.append((start, m.end()))
    for m in _SR_B64_WRAPPED.finditer(text):
        r = m.group(0)
        if (("+" in r or "/" in r) and _SR_B64_UPPER.search(r) and _SR_B64_LOWER.search(r)
                and _SR_B64_DIGIT.search(r)):
            spans.append(m.span())
    spans.sort()
    merged = []
    for s, e in spans:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    return merged


def sr_in_binary(spans, s, e):
    i = _sr_bisect.bisect_right(spans, (s, float("inf"))) - 1
    return i >= 0 and spans[i][1] >= e


SR_ESC_DEPTH = 5
_SR_ESC_HIDES = _sr_re.compile(r"\\(?:u00(?:3[0-9AaDd]|[4-7][0-9A-Fa-f]|2[BbDdEeFf])|/)")
_SR_ESC = _sr_re.compile(r"\\(?:u([0-9A-Fa-f]{4})|([\"\\/bfnrt]))")
_SR_ESC_CH = {'"': '"', "\\": "\\", "/": "/", "b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t"}


def _sr_unescape(s):
    out, segs, pos, vlen = [], [], 0, 0
    for m in _SR_ESC.finditer(s):
        if m.start() > pos:
            out.append(s[pos:m.start()])
            vlen += m.start() - pos
        segs.append((vlen, m.start(), m.end() - m.start()))
        out.append(chr(int(m.group(1), 16)) if m.group(1) else _SR_ESC_CH[m.group(2)])
        vlen += 1
        pos = m.end()
    out.append(s[pos:])
    return "".join(out), segs


def _sr_esc_src(segs, keys, p):
    i = _sr_bisect.bisect_right(keys, p) - 1
    if i < 0:
        return p, p + 1
    v, s, n = segs[i]
    if v == p:
        return s, s + n
    q = s + n + (p - v - 1)
    return q, q + 1


def sr_escaped_spans(text, find):
    if not _SR_ESC_HIDES.search(text):
        return []
    levels, view, found = [], text, []
    for _ in range(SR_ESC_DEPTH):
        view, segs = _sr_unescape(view)
        if not segs:
            break
        levels.append((segs, [v for v, _s, _n in segs]))
        for a, b in find(view):
            if a >= b:
                continue
            s, s_end = a, b - 1
            for segs_, keys in reversed(levels):
                s = _sr_esc_src(segs_, keys, s)[0]
                s_end = _sr_esc_src(segs_, keys, s_end)[1] - 1
            if text[s:s_end + 1] != view[a:b]:
                found.append((s, s_end + 1))
        if not _SR_ESC_HIDES.search(view):
            break
    found.sort()
    merged = []
    for s, e in found:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    return merged


def sr_escaped_views(text):
    if not _SR_ESC_HIDES.search(text):
        return []
    out, view = [], text
    for _ in range(SR_ESC_DEPTH):
        view, segs = _sr_unescape(view)
        if not segs:
            break
        out.append(view)
        if not _SR_ESC_HIDES.search(view):
            break
    return out

_SHARED = {name: (pat, check) for name, pat, check in sr_rules(raw_json=True)}
_SCRUB_DEVELOP = {"anthropic_key": re.compile(r'(?<![A-Za-z0-9_-])sk-ant-[A-Za-z0-9_-]{12,}'),
                  "session_token": re.compile(r'(?<![A-Za-z0-9_-])ge_sess_[A-Za-z0-9_-]{6,}')}
_SCRUB = [
    ("glued_password", _SHARED["glued_password"][0]),
    ("glued_bearer", _SHARED["glued_bearer"][0]),
    ("anthropic_key", re.compile(r'(?<![A-Za-z0-9_-])sk-ant-[A-Za-z0-9_-]{12}' + _sr_cb("A-Za-z0-9_-") + '*')),
    ("session_token", re.compile(r'(?<![A-Za-z0-9_-])ge_sess_[A-Za-z0-9_-]{6}' + _sr_cb("A-Za-z0-9_-") + '*')),
    ("github_token",  re.compile(r'(?<![A-Za-z0-9_-])(?:ghp_|github_pat_)(?:(?!AIza|ya29\.|1//|GOCSPX-|gsk_|xai-)[A-Za-z0-9_]){10,}')),
    ("bearer",        _SHARED["bearer"][0]),
    ("aws_akid",      re.compile(r'(?<![A-Za-z0-9_-])AKIA[0-9A-Z]{16}')),
    ("url_cred",      re.compile(r'(https?://[^/\s:@"\\]+:)[^/\s@"\\]+(@)')),
    ("auth_header",   _SHARED["auth_header"][0]),
    ("url_token",     re.compile(r'([Hh](?<![A-Za-z0-9+.-][Hh])[Tt][Tt][Pp][Ss]?://)(?=[A-Za-z0-9_-]{0,255}[0-9])'
                                 r'(?=[A-Za-z0-9_-]{0,255}[A-Za-z])[A-Za-z0-9_-]{16,256}(?=@)')),
]
_SCRUB += [(name, pat) for name, (pat, _check) in _SHARED.items() if name not in dict(_SCRUB)]
_EXTRA = {name.split(".", 1)[1]: (pat, check, mark) for name, pat, check, mark in sr_extra_rules(
    True, (PUBLIC_DOMAIN,), re.escape(PUBLIC_DOMAIN))}
_PII = frozenset(n.split(".", 1)[1] for n in SR_PII_RULES)
_SCRUB += [(name, pat) for name, (pat, _check, _mark) in _EXTRA.items()]
_SCRUB = [r for r in _SCRUB if r[0] != "jwt"] + [r for r in _SCRUB if r[0] == "jwt"]
_SR_PCT_BEFORE = re.compile(r"%[0-9A-Fa-f]{2}")


def _check_anthropic_key(m):
    s, i = m.string, m.start()
    after_sep = (i > 0 and s[i - 1] == "_") or (i >= 3 and _SR_PCT_BEFORE.fullmatch(s, i - 3, i))
    if after_sep and not _sr_cls_key_like(m.group(0)[len("sk-ant-"):]):
        return None
    return m.span()


_CHECKS = {**{n: (c, "[REDACTED]") for n, (_p, c) in _SHARED.items()},
           **{n: (c, mark) for n, (_p, c, mark) in _EXTRA.items()},
           "anthropic_key": (_check_anthropic_key, "[REDACTED]")}
_BIN_GUARDED = frozenset({"anthropic_key", "session_token", "github_token", "aws_akid"})
_PRECHECK = {**SR_PRECHECK, **{n.split(".", 1)[1]: subs for n, subs in SR_EXTRA_PRECHECK.items()}}
SCRUB_MODES = ("full", "secrets-only", "none")
_MAX_PASSES = 4
_JSON_SAFE = re.compile(r'(?:[^"\\]|\\[\s\S])*')


def _json_safe_span(text: str, s0: int, e0: int) -> bool:
    k = s0
    while k > 0 and text[k - 1] == "\\":
        k -= 1
    return (s0 - k) % 2 == 0 and _JSON_SAFE.fullmatch(text, s0, e0) is not None


_BAD_JSON_ESC = re.compile(r'(?<!\\)(?:\\\\)*\\(?:[^"\\/bfnrtu]|u(?![0-9A-Fa-f]{4}))')


def _plain_text_span(text: str, s0: int, e0: int) -> bool:
    a = text.rfind("\n", 0, s0) + 1
    return '"' not in text[s0:e0] and _BAD_JSON_ESC.search(text, a, s0) is not None


_NL = re.compile(r"\n")
_PEM_BEGIN = re.compile(r'-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----', re.I)
_PEM_END = re.compile(r'-----END [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----', re.I)
_PEM_STOP = re.compile('[^A-Za-z0-9+/=:,.\\- \t\r\n\\\\\u2192\u2502\u2503\u2551|#>*<;]')
_PEM_FIELD_SEP = re.compile(r'[ \t]*[,:]')
_PEM_MAX_BODY = 32768
_PEM_MARK = "[REDACTED-PRIVATE-KEY]"


def _escaped(text: str, i: int) -> bool:
    j = i
    while j > 0 and text[j - 1] == "\\":
        j -= 1
    return (i - j) % 2 == 1


def _pem_spans(text: str) -> list[tuple[int, int]]:
    if "-----" not in text:
        return []
    ends = list(_PEM_END.finditer(text))
    if not ends:
        return []
    end_starts = [m.start() for m in ends]
    spans: list[tuple[int, int]] = []
    skip = clean = 0
    for b in _PEM_BEGIN.finditer(text):
        if b.start() < skip:
            continue
        i = bisect.bisect_left(end_starts, b.end())
        if i == len(ends):
            break
        e = ends[i]
        if e.start() - b.end() > _PEM_MAX_BODY:
            continue
        lo = max(b.end(), clean)
        s = _PEM_STOP.search(text, lo, e.start()) if lo < e.start() else None
        while s and text[s.start()] == '"' and _escaped(text, s.start()) \
                and not _PEM_FIELD_SEP.match(text, s.start() + 1):
            s = _PEM_STOP.search(text, s.start() + 1, e.start())
        if s:
            skip = clean = s.start()
            continue
        clean = e.start()
        spans.append((b.start(), e.end()))
        skip = e.end()
    return spans


def _precheck_matches(pat, text: str, low: str, subs) -> "list":
    if len(low) != len(text):
        return list(pat.finditer(text))
    spans = []
    for sub in subs:
        i = low.find(sub)
        while i != -1:
            a, b = text.rfind("\n", 0, i) + 1, text.find("\n", i)
            b = len(text) if b == -1 else b
            spans.append((a, b))
            i = low.find(sub, b)
    if not spans:
        return []
    spans.sort()
    merged = [list(spans[0])]
    for a, b in spans[1:]:
        if a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    if sum(b - a for a, b in merged) * 2 > len(text):
        return list(pat.finditer(text))
    return [m for a, b in merged for m in pat.finditer(text, a, b)]


class _PemRawNum:
    __slots__ = ("token",)

    def __init__(self, token: str):
        self.token = token


def _pem_dump_line(red) -> str:
    nonce = uuid.uuid4().hex
    raws: dict = {}

    def default(o):
        if isinstance(o, _PemRawNum):
            ph = f"\x00rawnum-{nonce}-{len(raws)}\x00"
            raws[json.dumps(ph)] = o.token
            return ph
        raise TypeError(f"not JSON serializable: {type(o).__name__}")

    out = json.dumps(red, ensure_ascii=False, separators=(",", ":"), default=default)
    try:
        out.encode("utf-8")
    except UnicodeEncodeError:
        out = json.dumps(red, separators=(",", ":"), default=default)
    for ph, tok in raws.items():
        out = out.replace(ph, tok)
    return out


_DEEP_MAX = 600
_DEEP_MARK = '"[REDACTED-DEEP]"'
_DEEP_STRING = re.compile(r'"[^"\\]*(?:\\.[^"\\]*)*"?', re.S)
_DEEP_BRACKET = re.compile(r"[\[\]{}]")
_DEEP_SCALAR = re.compile(r'("[^"\\]*(?:\\.[^"\\]*)*"?)(\s*:)?|[^\s\[\]{}:,"]+', re.S)
_DEEP_PLAIN_KEY = re.compile(r'"[A-Za-z0-9_.\- ]{1,64}"')


def _too_deep(line: str, limit: int = _DEEP_MAX) -> bool:
    if line.count("[") + line.count("{") <= limit:
        return False
    stripped = _DEEP_STRING.sub("", line)
    depth = 0
    for m in _DEEP_BRACKET.finditer(stripped):
        if m.group() in "[{":
            depth += 1
            if depth > limit:
                return True
        else:
            depth -= 1
    return False


def _redact_deep(line: str, carry) -> str:
    clean: dict = {}

    def sub(m):
        s, colon = m.group(1), m.group(2)
        if s is None:
            return m.group(0) if m.group(0) in ("true", "false", "null") else "0"
        if colon is None:
            return _DEEP_MARK
        ok = clean.get(s)
        if ok is None:
            ok = clean[s] = bool(_DEEP_PLAIN_KEY.fullmatch(s)) and scrub(s)[0] == s
        return (s if ok else _DEEP_MARK) + colon

    out = _DEEP_SCALAR.sub(sub, line)
    last = None
    for last in _SR_PEMC_BEGIN.finditer(line):
        pass
    if last is not None and not _SR_PEMC_END.search(line, last.end()):
        carry.begin(kind=last.group(0)[11:-5].upper())
    elif _SR_PEMC_END.search(line):
        carry.close()
    elif carry.open:
        carry.seen = True
    carry.end_record()
    return out


def _pem_split_pass(text: str, hits: list, bump) -> str:
    if "-----" not in text:
        return text
    for tails in (False, True):
        spans, n = (sr_pem_orphan_spans(text), 0) if tails else sr_pem_concat_spans(text)
        if not spans:
            continue
        out, pos, ln = [], 0, 0
        for a, z in spans:
            ln += text.count("\n", pos, a)
            hits.append({"line": ln + 1, "col": a - text.rfind("\n", 0, a), "rule": "private_key", "chars": z - a})
            out.append(text[pos:a])
            out.append(_PEM_MARK + (sr_pem_breaks(text[a:z]) if tails else
                                    "".join(c for c in text[a:z] if c in "\r\n")))
            ln += text.count("\n", a, z)
            pos = z
        out.append(text[pos:])
        text = "".join(out)
        bump("private_key", n or len(spans))
    lines = text.split("\n")
    carry = SrPemCarry()
    for i, ln in enumerate(lines):
        new, n = sr_pem_list_redact(ln)
        if n:
            hits.append({"line": i + 1, "col": 1, "rule": "private_key", "chars": len(ln)})
            bump("private_key", n)
            lines[i] = ln = new
        if not ln.strip():
            continue
        if not (carry.open or "-----" in ln):
            carry.end_record()
            continue
        try:
            if _too_deep(ln):
                raise RecursionError("nesting over the cap")
            obj = json.loads(ln, parse_float=_PemRawNum, parse_int=_PemRawNum, parse_constant=_PemRawNum)
            carry.hits = 0
            red = sr_pem_walk(obj, carry)
            dumped = _pem_dump_line(red) if carry.hits else None
        except RecursionError:
            lines[i] = _redact_deep(ln, carry)
            hits.append({"line": i + 1, "col": 1, "rule": "deep_nesting", "chars": len(ln)})
            bump("deep_nesting")
            continue
        except ValueError:
            carry.close()
            continue
        carry.end_record()
        if carry.hits:
            lines[i] = dumped
            hits.append({"line": i + 1, "col": 1, "rule": "private_key", "chars": len(ln)})
            bump("private_key", carry.hits)
    return "\n".join(lines)


def scrub_detail(text: str, mode: str = "full") -> tuple[str, dict, list[dict]]:
    return sr_name_reconciled(lambda: _scrub_detail_run(text, mode),
                              alt_rules="sk-ant-" in text or "ge_sess_" in text)


def _scrub_detail_run(text: str, mode: str = "full") -> tuple[str, dict, list[dict]]:
    if mode not in SCRUB_MODES:
        raise ValueError(f"unknown scrub mode {mode!r}")
    counts: dict[str, int] = {}
    hits: list[dict] = []
    if mode == "none":
        return text, counts, hits

    def bump(k, n=1):
        counts[k] = counts.get(k, 0) + n

    line_map = list(range(1, text.count("\n") + 2))

    def _starts(t: str) -> list[int]:
        return [0] + [m.end() for m in _NL.finditer(t)]

    text = _pem_split_pass(text, hits, bump)
    pem = _pem_spans(text)
    if pem:
        starts = _starts(text)
        out, pos = [], 0
        for s0, e0 in pem:
            a = bisect.bisect_right(starts, s0) - 1
            b = bisect.bisect_right(starts, e0 - 1) - 1
            hits.append({"line": a + 1, "col": s0 - starts[a] + 1, "rule": "private_key",
                         "chars": e0 - s0, **({"to_line": b + 1} if b > a else {})})
            bump("private_key")
            breaks = "".join(c for c in text[s0:e0] if c in "\r\n")
            out.append(text[pos:s0]); out.append(_PEM_MARK + breaks); pos = e0
        out.append(text[pos:]); text = "".join(out)

    starts = None
    low = None
    ref = _SR_EXEMPT.ref
    for _pass in range(_MAX_PASSES):
        before = text
        for name, pat in _SCRUB:
            if mode == "secrets-only" and name in _PII:
                continue
            if ref and name in _SCRUB_DEVELOP:
                pat = _SCRUB_DEVELOP[name]
            out, pos = [], 0
            if name in _PRECHECK:
                if low is None:
                    low = text.lower()
                matches = _precheck_matches(pat, text, low, _PRECHECK[name])
            else:
                matches = pat.finditer(text)
            lout = [] if low is not None and len(low) == len(text) else None
            bin_spans = None
            for m in matches:
                if m.start() < pos:
                    continue
                if name in _PII or name in _BIN_GUARDED:
                    if bin_spans is None:
                        bin_spans = sr_binary_spans(text)
                    if sr_in_binary(bin_spans, m.start(), m.end()):
                        continue
                if starts is None:
                    starts = _starts(text)
                if name in _CHECKS:
                    check, mark = _CHECKS[name]
                    span = check(m)
                    if span is None or not (_json_safe_span(text, span[0], span[1]) or (
                            name == "homedir" and _plain_text_span(text, span[0], span[1]))):
                        continue
                    s0, e0 = span
                    m_end = max(m.end(), e0)
                    rep = text[m.start():s0] + mark + text[e0:m_end]
                elif name == "url_token":
                    m_end = m.end()
                    s0, e0, rep = m.start() + len(m.group(1)), m.end(), m.group(1) + "[REDACTED]"
                elif name == "url_cred":
                    m_end = m.end()
                    s0, e0 = m.start() + len(m.group(1)), m.end() - len(m.group(2))
                    rep = m.group(1) + "[REDACTED]" + m.group(2)
                else:
                    m_end = m.end()
                    s0, e0, rep = m.start(), m.end(), "[REDACTED]"
                li = bisect.bisect_right(starts, s0) - 1
                hits.append({"line": line_map[li], "col": s0 - starts[li] + 1, "rule": name, "chars": e0 - s0})
                bump(name)
                out.append(text[pos:m.start()]); out.append(rep)
                if lout is not None:
                    lout.append(low[pos:m.start()]); lout.append(rep.lower())
                pos = m_end
            if pos:
                out.append(text[pos:]); text = "".join(out)
                low = None if lout is None else "".join(lout) + low[pos:]
                if low is not None and len(low) != len(text):
                    low = None
                starts = None
        if text == before:
            break
    esc = sr_escaped_spans(text, _escaped_finder(mode))
    esc = [(s0, e0) for s0, e0 in esc if _json_safe_span(text, s0, e0)]
    if esc:
        starts = _starts(text)
        out, pos = [], 0
        for s0, e0 in esc:
            li = bisect.bisect_right(starts, s0) - 1
            hits.append({"line": line_map[li], "col": s0 - starts[li] + 1, "rule": "escaped_secret",
                         "chars": e0 - s0})
            bump("escaped_secret")
            out.append(text[pos:s0]); out.append("[REDACTED]"); pos = e0
        out.append(text[pos:]); text = "".join(out)
    hits.sort(key=lambda h: (h["line"], h["col"]))
    return text, {k: v for k, v in counts.items() if v}, hits


def _escaped_finder(mode: str):
    def find(view: str) -> list:
        spans = list(_pem_spans(view))
        for name, pat in _SCRUB:
            if name in _EXTRA:
                continue
            for m in pat.finditer(view):
                if name in _CHECKS:
                    sp = _CHECKS[name][0](m)
                elif name == "url_token":
                    sp = (m.start() + len(m.group(1)), m.end())
                elif name == "url_cred":
                    sp = (m.start() + len(m.group(1)), m.end() - len(m.group(2)))
                else:
                    sp = m.span()
                if sp is not None:
                    spans.append(sp)
        return spans
    return find


def scrub(text: str, mode: str = "full") -> tuple[str, dict]:
    t, counts, _ = scrub_detail(text, mode)
    return t, counts


def _sha256(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def _scrub_summary(counts: dict, hits: list[dict]) -> str:
    lines = sorted({h["line"] for h in hits})
    if not lines:
        return "client scrub: 0 lines changed"
    rules = ", ".join(f"{k}: {v}" for k, v in sorted(counts.items()))
    shown = ", ".join(map(str, lines[:20])) + (f", … (+{len(lines) - 20} more)" if len(lines) > 20 else "")
    return (f"client scrub: {len(lines)} line{'s' if len(lines) != 1 else ''} changed ({rules})"
            f" — line{'s' if len(lines) != 1 else ''} {shown}")


